import java.util.*;

class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        ArrayList<int[]>[] graph = new ArrayList[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            int u = e[0], v = e[1], t = e[2];
            graph[u].add(new int[]{v, t});
            graph[v].add(new int[]{u, t});
        }
        final int INF = Integer.MAX_VALUE / 4;
        int[][] dp = new int[n][maxTime + 1];
        for (int i = 0; i < n; i++) Arrays.fill(dp[i], INF);
        PriorityQueue<State> pq = new PriorityQueue<>(Comparator.comparingInt(s -> s.cost));
        dp[0][0] = passingFees[0];
        pq.offer(new State(0, 0, passingFees[0]));
        while (!pq.isEmpty()) {
            State cur = pq.poll();
            int node = cur.node, time = cur.time, cost = cur.cost;
            if (cost != dp[node][time]) continue;
            if (node == n - 1) {
                // Since pq is ordered by cost, this is the minimal cost to reach destination
                return cost;
            }
            for (int[] nei : graph[node]) {
                int v = nei[0], t = nei[1];
                int nt = time + t;
                if (nt > maxTime) continue;
                int nc = cost + passingFees[v];
                if (nc < dp[v][nt]) {
                    dp[v][nt] = nc;
                    pq.offer(new State(v, nt, nc));
                }
            }
        }
        return -1;
    }

    static class State {
        int node;
        int time;
        int cost;
        State(int n, int t, int c) { node = n; time = t; cost = c; }
    }
}

